Lemma gsi_1RB0RA_1LC0RA_1LD1RC_1LA0LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j A0_1RB0RA_1LC0RA_1LD1RC_1LA0LD.
