(** 1RB0RA_1LC0RB_0LC1LD_1RD0LA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RA_1LC0RB_0LC1LD_1RD0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StA
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StB
  | StC, S0 => mk S0 DL StC | StC, S1 => mk S1 DL StD
