(** ** The lap *)

Lemma lap_1RB0RA_1LC0RB_0LC1LD_1RD0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RA_1LC0RB_0LC1LD_1RD0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RA_1LC0RB_0LC1LD_1RD0LA B0_1RB0RA_1LC0RB_0LC1LD_1RD0LA B1_1RB0RA_1LC0RB_0LC1LD_1RD0LA 2 8 p j' [] []).
    + exact run_ovf_1RB0RA_1LC0RB_0LC1LD_1RD0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RA_1LC0RB_0LC1LD_1RD0LA p j' E).
    + exact (geo_1RB0RA_1LC0RB_0LC1LD_1RD0LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RA_1LC0RB_0LC1LD_1RD0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 6.
  assert (H : match csteps tm 6 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 6 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RA_1LC0RB_0LC1LD_1RD0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RA_1LC0RB_0LC1LD_1RD0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RA_1LC0RB_0LC1LD_1RD0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RA_1LC0RB_0LC1LD_1RD0LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RA_1LC0RB_0LC1LD_1RD0LA : forall t, ~ In t pins_1RB0RA_1LC0RB_0LC1LD_1RD0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
