    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RA_1LC0RB_0LC1LD_1RD0LA [SWin 1; SCycL 1 0; SWin 2; SCycR 1; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RA_1LC0RB_0LC1LD_1RD0LA [SWin 1; SCycL 1 0; SWin 2; SCycR 1; SWin 1; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
