(** ** The lap *)

Lemma lap_1RB0RA_1LC0RC_0LB1LD_1RB0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
