  - destruct (lapi_1RB0RA_1LC0RC_0LB1LD_1RB0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RA_1LC0RC_0LB1LD_1RB0LA B0_1RB0RA_1LC0RC_0LB1LD_1RB0LA B1_1RB0RA_1LC0RC_0LB1LD_1RB0LA 10 18 p j' [] []).
    + exact run_ovf_1RB0RA_1LC0RC_0LB1LD_1RB0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RA_1LC0RC_0LB1LD_1RB0LA p j' E).
    + exact (geo_1RB0RA_1LC0RC_0LB1LD_1RB0LA p j' E).
    + lia.
