(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RA_1LC0RD_0RA0LB_1LB0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ip q0 ++ [S0]) [] j A0_1RB0RA_1LC0RD_0RA0LB_1LB0LC.
