  unfold Cin_1RB0RA_1LC0RD_0RA0LB_1LB0LC, cden, AI0_1RB0RA_1LC0RD_0RA0LB_1LB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
