Lemma gen_1RB0RA_1LC0RD_0RA0LB_1LB0LC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB0RA_1LC0RD_0RA0LB_1LB0LC) = lift (Cin (Pos.succ v)).
Proof.
