  apply (nested_overflow_lift tm Cc Cin lapin_1RB0RA_1LC0RD_0RA0LB_1LB0LC p (pow2 j)).
  - exists (6 * j + 8), (cden [] [] j BB1_1RB0RA_1LC0RD_0RA0LB_1LB0LC).
    split; [lia|]. split; [| exact (gbo_1RB0RA_1LC0RD_0RA0LB_1LB0LC j)].
    rewrite (gso_1RB0RA_1LC0RD_0RA0LB_1LB0LC p j E).
    exact (srun_sound tm true true chb_1RB0RA_1LC0RD_0RA0LB_1LB0LC B0_1RB0RA_1LC0RD_0RA0LB_1LB0LC BB1_1RB0RA_1LC0RD_0RA0LB_1LB0LC 6 8
             run_boot_1RB0RA_1LC0RD_0RA0LB_1LB0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 12), (cden [] [] j B1_1RB0RA_1LC0RD_0RA0LB_1LB0LC).
    split; [| exact (geo_1RB0RA_1LC0RD_0RA0LB_1LB0LC p j E)].
