(** ** Bootstrap *)

Lemma boot_1RB0RA_1LC0RD_0RA0LB_1LB0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 6.
  assert (H : match csteps tm 6 c0 with
