(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RA_1LC0RD_0RA0LB_1LB0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RA_1LC0RD_0RA0LB_1LB0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RA_1LC0RD_0RA0LB_1LB0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RA_1LC0RD_0RA0LB_1LB0LC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0RA_1LC0RD_0RA0LB_1LB0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0RA_1LC0RD_0RA0LB_1LB0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0RA_1LC0RD_0RA0LB_1LB0LC t p (pow2 j)).
  - exists (6 * j + 8), (cden [] [] j BB1_1RB0RA_1LC0RD_0RA0LB_1LB0LC). split;
      [| exact (gbo_1RB0RA_1LC0RD_0RA0LB_1LB0LC j)].
    rewrite (gso_1RB0RA_1LC0RD_0RA0LB_1LB0LC p j E).
    exact (srun_sound tm true true chb_1RB0RA_1LC0RD_0RA0LB_1LB0LC B0_1RB0RA_1LC0RD_0RA0LB_1LB0LC BB1_1RB0RA_1LC0RD_0RA0LB_1LB0LC 6 8
             run_boot_1RB0RA_1LC0RD_0RA0LB_1LB0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0RA_1LC0RD_0RA0LB_1LB0LC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0RA_1LC0RD_0RA0LB_1LB0LC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RA_1LC0RD_0RA0LB_1LB0LC : forall t, ~ In t pins_1RB0RA_1LC0RD_0RA0LB_1LB0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0RA_1LC0RD_0RA0LB_1LB0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RA_1LC0RD_0RA0LB_1LB0LC [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RA_1LC0RD_0RA0LB_1LB0LC [SCycL 4 0; SWin 4; SCycR 2; SWinR 3] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RA_1LC0RD_0RA0LB_1LB0LC [SCycL 4 0; SWin 3] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RA_1LC0RD_0RA0LB_1LB0LC [SCycL 4 0; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RA_1LC0RD_0RA0LB_1LB0LC [SCycL 4 0; SWin 4; SCycR 2; SWinR 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RA_1LC0RD_0RA0LB_1LB0LC [SCycL 4 0; SWin 4] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RA_1LC0RD_0RA0LB_1LB0LC [SCycL 4 0; SWin 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RA_1LC0RD_0RA0LB_1LB0LC (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0RA_1LC0RD_0RA0LB_1LB0LC [SCycL 4 0; SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB0RA_1LC0RD_0RA0LB_1LB0LC : NeverQuasiHaltsTr tmm_1RB0RA_1LC0RD_0RA0LB_1LB0LC.
Proof.
  apply (glue_neverqhtr tmm_1RB0RA_1LC0RD_0RA0LB_1LB0LC pins_1RB0RA_1LC0RD_0RA0LB_1LB0LC Cc 1).
