(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0RA_1LC0RD_0RA0LB_1LB1RB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
