  exists (4 * j + 8), (cden (Ip q0 ++ [S0]) [] j A1_1RB0RA_1LC0RD_0RA0LB_1LB1RB).
  split; [lia|]. split; [| exact (gei_1RB0RA_1LC0RD_0RA0LB_1LB1RB p j q0 E)].
  rewrite (gsi_1RB0RA_1LC0RD_0RA0LB_1LB1RB p j q0 E).
  exact (srun_sound tm false true chi_1RB0RA_1LC0RD_0RA0LB_1LB1RB A0_1RB0RA_1LC0RD_0RA0LB_1LB1RB A1_1RB0RA_1LC0RD_0RA0LB_1LB1RB 4 8
           run_int_1RB0RA_1LC0RD_0RA0LB_1LB1RB (Ip q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB0RA_1LC0RD_0RA0LB_1LB1RB : forall p j, cview p = (S j, None) ->
