Lemma geo_1RB0RA_1LC0RD_0RA0LB_1LB1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RA_1LC0RD_0RA0LB_1LB1RB) = lift (Cc (Pos.succ p)).
