Lemma lapi_1RB0RA_1LC1RB_0RA0LD_1LB0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0RA_1LC1RB_0RA0LD_1LB0LD p q0 E) as (HA & HB).
    exists (0 * 0 + 8), (cden (Kp q0 ++ [S0]) [] 0 Z1_1RB0RA_1LC1RB_0RA0LD_1LB0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_1RB0RA_1LC1RB_0RA0LD_1LB0LD Z0_1RB0RA_1LC1RB_0RA0LD_1LB0LD Z1_1RB0RA_1LC1RB_0RA0LD_1LB0LD 0 8
             run_z_1RB0RA_1LC1RB_0RA0LD_1LB0LD (Kp q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
