  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RA_1LC1RB_0RA1LD_0LB0LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RA_1LC1RB_0RA1LD_0LB0LC B0_1RB0RA_1LC1RB_0RA1LD_0LB0LC B1_1RB0RA_1LC1RB_0RA1LD_0LB0LC 4 11 p j' [] []).
    + exact run_ovf_1RB0RA_1LC1RB_0RA1LD_0LB0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RA_1LC1RB_0RA1LD_0LB0LC p j' E).
    + exact (geo_1RB0RA_1LC1RB_0RA1LD_0LB0LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RA_1LC1RB_0RA1LD_0LB0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
