Lemma fireo_1RB0RA_1LC1RB_0RA1LD_0LB0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RA_1LC1RB_0RA1LD_0LB0LC = Some t ->
  forall p j, cview p = (S j, None) ->
