    apply (lap_of_run tm Cc true true cho_1RB0RA_1LC1RC_0RA0LD_1LB0LC B0_1RB0RA_1LC1RC_0RA0LD_1LB0LC B1_1RB0RA_1LC1RC_0RA0LD_1LB0LC 8 16 p j' [] []).
