(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RA_1RC0RA_1LD1RA_1LA0LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_000_001_00 q0 ++ [S1;S0]) [] j A0_1RB0RA_1RC0RA_1LD1RA_1LA0LD.
Proof.
  intros p j q0 E. destruct (Alph_000_001_00.cview_some_Alph_000_001_00 p j q0 E) as (H1 & _).
  unfold Cc_1RB0RA_1RC0RA_1LD1RA_1LA0LD, cden, A0_1RB0RA_1RC0RA_1LD1RA_1LA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S1;S0;S0] where the anchor has [S1;S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB0RA_1RC0RA_1LD1RA_1LA0LD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_000_001_00 q0 ++ [S1;S0]) [] j A1_1RB0RA_1RC0RA_1LD1RA_1LA0LD) = lift (Cc (Pos.succ p)).
Proof.
