Definition mk_1RB0RA_1RC0RA_1LD1RB_1LA0LD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0RA_1RC0RA_1LD1RB_1LA0LD.

(** 1RB0RA_1RC0RA_1LD1RB_1LA0LD *)
(** 1RB0RA_1RC0RA_1LD1RB_1LA0LD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RA_1RC0RA_1LD1RB_1LA0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StA
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DR StA
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S0 DL StD end.

(** Its mirror 1LB0LA_1LC0LA_1RD1LB_1RA0RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0RA_1RC0RA_1LD1RB_1LA0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DL StA
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DL StA
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S0 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RA_1RC0RA_1LD1RB_1LA0LD : list Instr := [].
Definition tmw_1RB0RA_1RC0RA_1LD1RB_1LA0LD : TM := tm_wrap_trs tmm_1RB0RA_1RC0RA_1LD1RB_1LA0LD pins_1RB0RA_1RC0RA_1LD1RB_1LA0LD.
Local Notation tm := tmw_1RB0RA_1RC0RA_1LD1RB_1LA0LD.

Lemma mirror_ok_1RB0RA_1RC0RA_1LD1RB_1LA0LD : mirror_tm tm_1RB0RA_1RC0RA_1LD1RB_1LA0LD = tmm_1RB0RA_1RC0RA_1LD1RB_1LA0LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0RA_1RC0RA_1LD1RB_1LA0LD (p : positive) : cconf := (StC, (Bp p ++ [S0], S0, [S1;S1])).
Local Notation Cc := Cc_1RB0RA_1RC0RA_1LD1RB_1LA0LD.

(** ** The certificate *)

Definition A0_1RB0RA_1RC0RA_1LD1RB_1LA0LD : sconf := mkC StC (mkS [] [S0;S1] 1 0 [S0;S0]) S0 (mkS [S1;S1] [] 0 0 []).
Definition A1_1RB0RA_1RC0RA_1LD1RB_1LA0LD : sconf := mkC StC (mkS [] [S0;S0] 1 0 [S0;S1]) S0 (mkS [S1;S1;S0;S0] [] 0 0 []).
