Lemma geo_1RB0RA_1RC1LA_1LD1RC_1LA0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RA_1RC1LA_1LD1RC_1LA0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
