Lemma lapi_1RB0RB_0LB1RC_0LD1RA_1RB1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
