Lemma geo_1RB0RB_0LB1RC_0LD1RA_1RB1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RB_0LB1RC_0LD1RA_1RB1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_101_111_1.cview_none_Alph_101_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RB_0LB1RC_0LD1RA_1RB1LD
             = (StC, (rep [S1;S0;S1] (S j) ++ [S1;S0;S1;S1;S1], S0, []))).
  { unfold cden, B1_1RB0RB_0LB1RC_0LD1RA_1RB1LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S0;S1] (S j) ++ [S1;S0;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0RB_0LB1RC_0LD1RA_1RB1LD. rewrite H2.
