    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RB_0LC0RA_1LA0LD_1RA1LC B0_1RB0RB_0LC0RA_1LA0LD_1RA1LC B1_1RB0RB_0LC0RA_1LA0LD_1RA1LC 4 12 p j' [] []).
    + exact run_ovf_1RB0RB_0LC0RA_1LA0LD_1RA1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RB_0LC0RA_1LA0LD_1RA1LC p j' E).
    + exact (geo_1RB0RB_0LC0RA_1LA0LD_1RA1LC p j' E).
    + lia.
