  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RB_0LC0RA_1LA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB0RB_0LC0RA_1LA0LD_1RA1LC : NeverQuasiHaltsTr tm_1RB0RB_0LC0RA_1LA0LD_1RA1LC.
Proof.
  apply (glue_neverqhtr tm_1RB0RB_0LC0RA_1LA0LD_1RA1LC pins_1RB0RB_0LC0RA_1LA0LD_1RA1LC Cc 1).
