    apply (lap_of_run tm Cc true true cho_1RB0RB_0LC0RA_1LD0LD_1RA1LC B0_1RB0RB_0LC0RA_1LD0LD_1RA1LC B1_1RB0RB_0LC0RA_1LD0LD_1RA1LC 4 8 p j' [] []).
