    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_0LC0RA_1LD0LD_1RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_0LC0RA_1LD0LD_1RA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
