(** ** The lap *)

Lemma lap_1RB0RB_0LC0RA_1RA0LD_0RB1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
