    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0RB_0LC0RA_1RA0LD_0RB1LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RB_0LC0RA_1RA0LD_0RB1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_0LC0RA_1RA0LD_0RB1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_0LC0RA_1RA0LD_0RB1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RB_0LC0RA_1RA0LD_0RB1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RB_0LC0RA_1RA0LD_0RB1LC p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB0RB_0LC0RA_1RA0LD_0RB1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB0RB_0LC0RA_1RA0LD_0RB1LC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB0RB_0LC0RA_1RA0LD_0RB1LC p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB0RB_0LC0RA_1RA0LD_0RB1LC p j q0 E)].
Qed.

(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0RB_0LC0RA_1RA0LD_0RB1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0RB_0LC0RA_1RA0LD_0RB1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0RB_0LC0RA_1RA0LD_0RB1LC t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB0RB_0LC0RA_1RA0LD_0RB1LC). split;
      [| exact (gbo_1RB0RB_0LC0RA_1RA0LD_0RB1LC j)].
    rewrite (gso_1RB0RB_0LC0RA_1RA0LD_0RB1LC p j E).
    exact (srun_sound tm true true chb_1RB0RB_0LC0RA_1RA0LD_0RB1LC B0_1RB0RB_0LC0RA_1RA0LD_0RB1LC BB1_1RB0RB_0LC0RA_1RA0LD_0RB1LC 4 8
             run_boot_1RB0RB_0LC0RA_1RA0LD_0RB1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0RB_0LC0RA_1RA0LD_0RB1LC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0RB_0LC0RA_1RA0LD_0RB1LC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RB_0LC0RA_1RA0LD_0RB1LC : forall t, ~ In t pins_1RB0RB_0LC0RA_1RA0LD_0RB1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RB_0LC0RA_1RA0LD_0RB1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0RB_0LC0RA_1RA0LD_0RB1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 6]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RB_0LC0RA_1RA0LD_0RB1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RB_0LC0RA_1RA0LD_0RB1LC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RB_0LC0RA_1RA0LD_0RB1LC (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0RB_0LC0RA_1RA0LD_0RB1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 5] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RB_0LC0RA_1RA0LD_0RB1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_0LC0RA_1RA0LD_0RB1LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB0RB_0LC0RA_1RA0LD_0RB1LC (StD, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB0RB_0LC0RA_1RA0LD_0RB1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RB_0LC0RA_1RA0LD_0RB1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB0RB_0LC0RA_1RA0LD_0RB1LC : NeverQuasiHaltsTr tm_1RB0RB_0LC0RA_1RA0LD_0RB1LC.
Proof.
  apply (glue_neverqhtr tm_1RB0RB_0LC0RA_1RA0LD_0RB1LC pins_1RB0RB_0LC0RA_1RA0LD_0RB1LC Cc 1).
  - exact boot_1RB0RB_0LC0RA_1RA0LD_0RB1LC.
  - intros p _. apply lap_1RB0RB_0LC0RA_1RA0LD_0RB1LC.
  - intros t Ht p _. apply fire_1RB0RB_0LC0RA_1RA0LD_0RB1LC. exact Ht.
Qed.

Theorem nonhalt_1RB0RB_0LC0RA_1RA0LD_0RB1LC : NonHalt tm_1RB0RB_0LC0RA_1RA0LD_0RB1LC.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB0RB_0LC0RA_1RA0LD_0RB1LC. Qed.

