Lemma gsi_1RB0RB_0LC0RB_1RA0LD_1LC0RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S1;S0]) [] j A0_1RB0RB_0LC0RB_1RA0LD_1LC0RA.
