Lemma fireo_1RB0RB_0LC0RB_1RA0LD_1LC0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_0LC0RB_1RA0LD_1LC0RA = Some t ->
