      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RB_0LC0RB_1RA0LD_1LC0RA (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0RB_0LC0RB_1RA0LD_1LC0RA [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 3] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RB_0LC0RB_1RA0LD_1LC0RA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RB_0LC0RB_1RA0LD_1LC0RA (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0RB_0LC0RB_1RA0LD_1LC0RA [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 7] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RB_0LC0RB_1RA0LD_1LC0RA (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0RB_0LC0RB_1RA0LD_1LC0RA [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_0LC0RB_1RA0LD_1LC0RA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RB_0LC0RB_1RA0LD_1LC0RA (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0RB_0LC0RB_1RA0LD_1LC0RA [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RB_0LC0RB_1RA0LD_1LC0RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB0RB_0LC0RB_1RA0LD_1LC0RA : NeverQuasiHaltsTr tm_1RB0RB_0LC0RB_1RA0LD_1LC0RA.
