Lemma geo_1RB0RB_0LC1RA_0LC1LD_1RB1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RB_0LC1RA_0LC1LD_1RB1LD) = lift (Cc (Pos.succ p)).
