(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RB_0LC1RA_0LD1LC_1RD1RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Mp q0 ++ [S0]) [] j A0_1RB0RB_0LC1RA_0LD1LC_1RD1RA.
Proof.
  intros p j q0 E. destruct (MpCounter.cview_some_M p j q0 E) as (H1 & _).
  unfold Cc_1RB0RB_0LC1RA_0LD1LC_1RD1RA, cden, A0_1RB0RB_0LC1RA_0LD1LC_1RD1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0;S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB0RB_0LC1RA_0LD1LC_1RD1RA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Mp q0 ++ [S0]) [] j A1_1RB0RB_0LC1RA_0LD1LC_1RD1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (MpCounter.cview_some_M p j q0 E) as (_ & H2).
  unfold Cc_1RB0RB_0LC1RA_0LD1LC_1RD1RA, cden, A1_1RB0RB_0LC1RA_0LD1LC_1RD1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0;S0]) with ((([]) ++ [S0]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0RB_0LC1RA_0LD1LC_1RD1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
