  intros p j q0 E.
  exists (4 * j + 12), (cden (Mp q0 ++ [S0]) [] j A1_1RB0RB_0LC1RA_0LD1LC_1RD1RA).
  split; [lia|]. split; [| exact (gei_1RB0RB_0LC1RA_0LD1LC_1RD1RA p j q0 E)].
  rewrite (gsi_1RB0RB_0LC1RA_0LD1LC_1RD1RA p j q0 E).
