Definition chn_1RB0RB_0LC1RA_0LD1LD_1RB1LD : list lstep := [SWin 1; SWinR 5; SCycL 2 0; SWin 4; SCycR 2; SWin 6].

Lemma run_inner_1RB0RB_0LC1RA_0LD1LD_1RB1LD : srun tm false true chn_1RB0RB_0LC1RA_0LD1LD_1RB1LD AI0_1RB0RB_0LC1RA_0LD1LD_1RB1LD = Some (AI1_1RB0RB_0LC1RA_0LD1LD_1RB1LD, 4, 16).
