(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0RB_0LC1RA_0LD1LD_1RB1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S0;S0;S0] [] 0 0 []).
Definition chb_1RB0RB_0LC1RA_0LD1LD_1RB1LD : list lstep := [SWin 2; SWinR 4; SCycL 2 0; SWin 6; SCycR 2; SWin 4; SRotL 1; SWin 1].

Lemma run_boot_1RB0RB_0LC1RA_0LD1LD_1RB1LD : srun tm true true chb_1RB0RB_0LC1RA_0LD1LD_1RB1LD B0_1RB0RB_0LC1RA_0LD1LD_1RB1LD = Some (BB1_1RB0RB_0LC1RA_0LD1LD_1RB1LD, 4, 17).
