(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0RB_0LC1RA_0LD1LD_1RB1LD : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
