Lemma gen_1RB0RB_0LC1RA_0LD1LD_1RB1LD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB0RB_0LC1RA_0LD1LD_1RB1LD) = lift (Cin (Pos.succ v)).
