(** The chain into this family lands on its anchor up to 0/3
    trailing blanks. *)
Lemma gbo_1RB0RB_0LC1RA_0LD1LD_1RB1LD : forall j, lift (cden [] [] j BB1_1RB0RB_0LC1RA_0LD1LD_1RB1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0RB_0LC1RA_0LD1LD_1RB1LD = (StD, (rep [S1;S0] j ++ [S1;S1], S0, ((([S1]) ++ [S0]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_1RB0RB_0LC1RA_0LD1LD_1RB1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1], S0, [S1]))).
  { unfold Cin_1RB0RB_0LC1RA_0LD1LD_1RB1LD. rewrite epow2_1RB0RB_0LC1RA_0LD1LD_1RB1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0RB_0LC1RA_0LD1LD_1RB1LD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0RB_0LC1RA_0LD1LD_1RB1LD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0RB_0LC1RA_0LD1LD_1RB1LD.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0RB_0LC1RA_0LD1LD_1RB1LD, cden, BE0_1RB0RB_0LC1RA_0LD1LD_1RB1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0RB_0LC1RA_0LD1LD_1RB1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB0RB_0LC1RA_0LD1LD_1RB1LD. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0RB_0LC1RA_0LD1LD_1RB1LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0RB_0LC1RA_0LD1LD_1RB1LD p (pow2 j)).
  - exists (4 * j + 17), (cden [] [] j BB1_1RB0RB_0LC1RA_0LD1LD_1RB1LD).
    split; [lia|]. split; [| exact (gbo_1RB0RB_0LC1RA_0LD1LD_1RB1LD j)].
    rewrite (gso_1RB0RB_0LC1RA_0LD1LD_1RB1LD p j E).
    exact (srun_sound tm true true chb_1RB0RB_0LC1RA_0LD1LD_1RB1LD B0_1RB0RB_0LC1RA_0LD1LD_1RB1LD BB1_1RB0RB_0LC1RA_0LD1LD_1RB1LD 4 17
             run_boot_1RB0RB_0LC1RA_0LD1LD_1RB1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 19), (cden [] [] j B1_1RB0RB_0LC1RA_0LD1LD_1RB1LD).
    split; [| exact (geo_1RB0RB_0LC1RA_0LD1LD_1RB1LD p j E)].
    rewrite (gxi_1RB0RB_0LC1RA_0LD1LD_1RB1LD j).
    exact (srun_sound tm true true che_1RB0RB_0LC1RA_0LD1LD_1RB1LD BE0_1RB0RB_0LC1RA_0LD1LD_1RB1LD B1_1RB0RB_0LC1RA_0LD1LD_1RB1LD 4 19
             run_exit_1RB0RB_0LC1RA_0LD1LD_1RB1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0RB_0LC1RA_0LD1LD_1RB1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RB_0LC1RA_0LD1LD_1RB1LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0RB_0LC1RA_0LD1LD_1RB1LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RB_0LC1RA_0LD1LD_1RB1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 18.
  assert (H : match csteps tm 18 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 18 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_0LC1RA_0LD1LD_1RB1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_0LC1RA_0LD1LD_1RB1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RB_0LC1RA_0LD1LD_1RB1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RB_0LC1RA_0LD1LD_1RB1LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RB_0LC1RA_0LD1LD_1RB1LD : forall t, ~ In t pins_1RB0RB_0LC1RA_0LD1LD_1RB1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0RB_0LC1RA_0LD1LD_1RB1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RA_0LD1LD_1RB1LD [SWin 2; SWinR 4; SCycL 2 0; SWin 6; SCycR 2; SWin 4; SRotL 1; SWin 1; SWin 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RA_0LD1LD_1RB1LD [SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RA_0LD1LD_1RB1LD [SWin 2; SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RA_0LD1LD_1RB1LD [SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RA_0LD1LD_1RB1LD [SWin 2; SWinR 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RA_0LD1LD_1RB1LD [SWin 2; SWinR 4; SCycL 2 0; SWin 6; SCycR 2; SWin 4; SRotL 1; SWin 1; SWin 4] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RA_0LD1LD_1RB1LD [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RA_0LD1LD_1RB1LD [SWin 2; SWinR 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB0RB_0LC1RA_0LD1LD_1RB1LD : NeverQuasiHaltsTr tm_1RB0RB_0LC1RA_0LD1LD_1RB1LD.
Proof.
  apply (glue_neverqhtr tm_1RB0RB_0LC1RA_0LD1LD_1RB1LD pins_1RB0RB_0LC1RA_0LD1LD_1RB1LD Cc 1).
  - exact boot_1RB0RB_0LC1RA_0LD1LD_1RB1LD.
  - intros p _. apply lap_1RB0RB_0LC1RA_0LD1LD_1RB1LD.
