  apply (nested_overflow_lift tm Cc Cin lapin_1RB0RB_0LC1RA_0LD1RC_1RB1LD p (pow2 j)).
  - exists (4 * j + 17), (cden [] [] j BB1_1RB0RB_0LC1RA_0LD1RC_1RB1LD).
    split; [lia|]. split; [| exact (gbo_1RB0RB_0LC1RA_0LD1RC_1RB1LD j)].
