Lemma firex_1RB0RB_0LC1RA_1LD1LC_1RB1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0RB_0LC1RA_1LD1LC_1RB1LD = Some t ->
