  apply (fire_via_fill tm Cc Cin lapin_1RB0RB_0LC1RA_1LD1LC_1RB1LD t p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_1RB0RB_0LC1RA_1LD1LC_1RB1LD). split;
      [| exact (gbo_1RB0RB_0LC1RA_1LD1LC_1RB1LD j)].
