    exact (srun_sound tm true true chb_1RB0RB_0LC1RA_1LD1LC_1RB1LD B0_1RB0RB_0LC1RA_1LD1LC_1RB1LD BB1_1RB0RB_0LC1RA_1LD1LC_1RB1LD 4 9
             run_boot_1RB0RB_0LC1RA_1LD1LC_1RB1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
