Lemma gsi_1RB0RB_0LC1RD_1LB1LA_1LC0RD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0RB_0LC1RD_1LB1LA_1LC0RD.
