(** ** The lap *)

Lemma lap_1RB0RB_0LC1RD_1LB1LA_1LC0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RB_0LC1RD_1LB1LA_1LC0RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0RB_0LC1RD_1LB1LA_1LC0RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RB_0LC1RD_1LB1LA_1LC0RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 17.
  assert (H : match csteps tm 17 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 17 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_0LC1RD_1LB1LA_1LC0RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_0LC1RD_1LB1LA_1LC0RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RB_0LC1RD_1LB1LA_1LC0RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RB_0LC1RD_1LB1LA_1LC0RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RB_0LC1RD_1LB1LA_1LC0RD : forall t, ~ In t pins_1RB0RB_0LC1RD_1LB1LA_1LC0RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0RB_0LC1RD_1LB1LA_1LC0RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RD_1LB1LA_1LC0RD [SWin 1; SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RD_1LB1LA_1LC0RD [SWin 1; SWinR 5] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RD_1LB1LA_1LC0RD [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RD_1LB1LA_1LC0RD [SWin 1; SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RD_1LB1LA_1LC0RD [SWin 1; SWinR 7; SRotL 1; SWin 1; SCycL 2 0; SWin 3] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RD_1LB1LA_1LC0RD [SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RD_1LB1LA_1LC0RD [SWin 1; SWinR 3] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RD_1LB1LA_1LC0RD [SWin 1; SWinR 7] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB0RB_0LC1RD_1LB1LA_1LC0RD : NeverQuasiHaltsTr tmm_1RB0RB_0LC1RD_1LB1LA_1LC0RD.
Proof.
  apply (glue_neverqhtr tmm_1RB0RB_0LC1RD_1LB1LA_1LC0RD pins_1RB0RB_0LC1RD_1LB1LA_1LC0RD Cc 1).
  - exact boot_1RB0RB_0LC1RD_1LB1LA_1LC0RD.
  - intros p _. apply lap_1RB0RB_0LC1RD_1LB1LA_1LC0RD.
  - intros t Ht p _. apply fire_1RB0RB_0LC1RD_1LB1LA_1LC0RD. exact Ht.
Qed.

Theorem nqhtr_1RB0RB_0LC1RD_1LB1LA_1LC0RD : NeverQuasiHaltsTr tm_1RB0RB_0LC1RD_1LB1LA_1LC0RD.
Proof. apply (neverqhtr_mirror tm_1RB0RB_0LC1RD_1LB1LA_1LC0RD). rewrite mirror_ok_1RB0RB_0LC1RD_1LB1LA_1LC0RD. exact nqhtrm_1RB0RB_0LC1RD_1LB1LA_1LC0RD. Qed.

Theorem nonhalt_1RB0RB_0LC1RD_1LB1LA_1LC0RD : NonHalt tm_1RB0RB_0LC1RD_1LB1LA_1LC0RD.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB0RB_0LC1RD_1LB1LA_1LC0RD. Qed.

