Lemma gen_1RB0RB_0LC1RD_1RB1LC_0LA1RA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_1RB0RB_0LC1RD_1RB1LC_0LA1RA) = lift (Cin (Pos.succ v)).
