    apply (lap_of_run tm Cc true true cho_1RB0RB_0LC1RD_1RB1LC_0LD1RA B0_1RB0RB_0LC1RD_1RB1LC_0LD1RA B1_1RB0RB_0LC1RD_1RB1LC_0LD1RA 6 26 p j' [] []).
