Definition mk_1RB0RB_0RC0LD_1LD1RC_0LA1LB (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0RB_0RC0LD_1LD1RC_0LA1LB.

(** 1RB0RB_0RC0LD_1LD1RC_0LA1LB *)
(** 1RB0RB_0RC0LD_1LD1RC_0LA1LB -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RB_0RC0LD_1LD1RC_0LA1LB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StB
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DL StB end.

(** Its mirror 1LB0LB_0LC0RD_1RD1LC_0RA1RB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0RB_0RC0LD_1LD1RC_0LA1LB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DL StB
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S1 DR StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RB_0RC0LD_1LD1RC_0LA1LB : list Instr := [].
Definition tmw_1RB0RB_0RC0LD_1LD1RC_0LA1LB : TM := tm_wrap_trs tmm_1RB0RB_0RC0LD_1LD1RC_0LA1LB pins_1RB0RB_0RC0LD_1LD1RC_0LA1LB.
Local Notation tm := tmw_1RB0RB_0RC0LD_1LD1RC_0LA1LB.

Lemma mirror_ok_1RB0RB_0RC0LD_1LD1RC_0LA1LB : mirror_tm tm_1RB0RB_0RC0LD_1LD1RC_0LA1LB = tmm_1RB0RB_0RC0LD_1LD1RC_0LA1LB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

