(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RB_0RC0LD_1LD1RC_0LA1LB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0RB_0RC0LD_1LD1RC_0LA1LB.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_1RB0RB_0RC0LD_1LD1RC_0LA1LB, cden, A0_1RB0RB_0RC0LD_1LD1RC_0LA1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0RB_0RC0LD_1LD1RC_0LA1LB : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB0RB_0RC0LD_1LD1RC_0LA1LB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_1RB0RB_0RC0LD_1LD1RC_0LA1LB, cden, A1_1RB0RB_0RC0LD_1LD1RC_0LA1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0RB_0RC0LD_1LD1RC_0LA1LB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_1RB0RB_0RC0LD_1LD1RC_0LA1LB p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0RB_0RC0LD_1LD1RC_0LA1LB A0_1RB0RB_0RC0LD_1LD1RC_0LA1LB A1_1RB0RB_0RC0LD_1LD1RC_0LA1LB 4 4
             run_int_1RB0RB_0RC0LD_1LD1RC_0LA1LB (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0RB_0RC0LD_1LD1RC_0LA1LB p j q0 E).
Qed.

Lemma gso_1RB0RB_0RC0LD_1LD1RC_0LA1LB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RB_0RC0LD_1LD1RC_0LA1LB.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_1RB0RB_0RC0LD_1LD1RC_0LA1LB, cden, B0_1RB0RB_0RC0LD_1LD1RC_0LA1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0RB_0RC0LD_1LD1RC_0LA1LB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RB_0RC0LD_1LD1RC_0LA1LB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RB_0RC0LD_1LD1RC_0LA1LB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RB_0RC0LD_1LD1RC_0LA1LB
             = (StB, (rep [S1;S0] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB0RB_0RC0LD_1LD1RC_0LA1LB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0RB_0RC0LD_1LD1RC_0LA1LB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB0RB_0RC0LD_1LD1RC_0LA1LB. reflexivity.
Qed.

Lemma gsn_1RB0RB_0RC0LD_1LD1RC_0LA1LB : forall v i q0, cview v = (i, Some q0) ->
